bcftools query -f '%ID\t%INFO/PERIOD\t[%GB]\n' NA12878.vcf.gz | awk -F'\t' -v OFS='\t' '
  NR == FNR { ce[$1] = $6; next }
  $3 == "." { print $1, "."; next }
  { split($3, gb, "|"); out = $1
    for (i = 1; i <= 2; i++) { t = ce[$1] * $2 + gb[i]; r = t % $2
      out = out OFS (t - r) / $2 (r ? "." r : "") }
    print out }' isfg_ranges_grch38.tsv - | column -t

